def copy_participation_to_slots(apps, schema_editor):
    Connection = apps.get_model('modeling', 'Connection')
    Slot = apps.get_model('modeling', 'ConnectionParticipation')
    database = schema_editor.connection.alias
    for connection in Connection.objects.using(database).all().iterator():
        member_ids = list(connection.participating_members.using(database).order_by('client_key', 'pk').values_list('pk', flat=True))
        Slot.objects.using(database).bulk_create([
            Slot(connection_id=connection.pk, member_id=member_id, position=position)
            for position, member_id in enumerate(member_ids)
        ])


def copy_slots_to_legacy_participation(apps, schema_editor):
    Connection = apps.get_model('modeling', 'Connection')
    Slot = apps.get_model('modeling', 'ConnectionParticipation')
    database = schema_editor.connection.alias
    if Slot.objects.using(database).filter(member_id__isnull=True).exists():
        raise IrreversibleError('Cannot roll back a draft with a participation gap.')
    Legacy = Connection.participating_members.through
    Legacy.objects.using(database).bulk_create([
        Legacy(connection_id=connection_id, physicalmember_id=member_id)
        for connection_id, member_id in Slot.objects.using(database).exclude(member_id__isnull=True).values_list('connection_id', 'member_id')
    ])


